package com.caf.bt7274.client;
import com.caf.bt7274.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.phys.Vec3;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Isolated survival flight QA. No production motion/physics values changed. */
@EventBusSubscriber(modid="bt7274",value=Dist.CLIENT)
public final class BbEjectionFlightQa {
 private static final Path OUT=Path.of(System.getProperty("bt.qaOut","F:/自制武器源文件/08_BT7274/previews/bb27_ejection_flight"));
 private static UUID titanId,pilotId;private static int tick;private static boolean initialized,confirmed,started,released,ascending,descending,landed,serverComplete;private static int releaseServerTick,landServerTick;private static double peakY,lastY;
 private static void write(String file,Map<String,Object> row){try{Files.createDirectories(OUT);Files.writeString(OUT.resolve(file),new com.google.gson.Gson().toJson(row)+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception e){throw new RuntimeException(e);}}
 private static void check(boolean good,String text){if(!good)throw new AssertionError(text);try{Files.writeString(OUT.resolve("assertions.log"),"PASS "+text+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception e){throw new RuntimeException(e);}}
 private static void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> task){var mc=Minecraft.getInstance();var id=mc.player.getUUID();mc.getSingleplayerServer().execute(()->task.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(id)));}
 public static Map<String,Object> context(){var mc=Minecraft.getInstance();Map<String,Object> m=new LinkedHashMap<>();m.put("qa_client_tick",tick);m.put("wall_time_unix_ms",System.currentTimeMillis());if(mc.player==null||mc.level==null)return m;var p=mc.player;m.put("game_tick",mc.level.getGameTime());m.put("pilot_y",p.getY());m.put("pilot_vy",p.getDeltaMovement().y);m.put("mounted",p.getVehicle()!=null);m.put("flying",p.getAbilities().flying);m.put("mayfly",p.getAbilities().mayfly);m.put("on_ground",p.onGround());m.put("no_gravity",p.isNoGravity());m.put("window_active",mc.isWindowActive());m.put("G_key_down",TitanClient.EJECT.isDown());for(var e:mc.level.entitiesForRendering())if(e instanceof TitanEntity t&&t.getUUID().equals(titanId)){m.put("body_action",t.getAction());m.put("body_start_tick",t.getActionStartTick());m.put("body_elapsed_seconds",(mc.level.getGameTime()-t.getActionStartTick())/20.0);m.put("eject_remaining",t.getEjectTicks());m.put("eject_confirm",t.getEjectConfirmTicks());break;}return m;}
 @SubscribeEvent public static void before(ClientTickEvent.Pre e){if(!Boolean.getBoolean("bt.bbEjectionFlightQa"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;for(var key:List.of(mc.options.keyShift,mc.options.keyJump,mc.options.keyUp,mc.options.keyDown,mc.options.keyLeft,mc.options.keyRight,mc.options.keyAttack,mc.options.keyUse))key.setDown(false);mc.player.getAbilities().flying=false;mc.player.getAbilities().mayfly=false;mc.player.setNoGravity(false);TitanClient.EJECT.setDown(tick==109||tick==114);}
 @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!Boolean.getBoolean("bt.bbEjectionFlightQa"))return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;tick++;
  try{
   if(tick==1){Files.createDirectories(OUT);for(String file:List.of("complete.txt","assertions.log","flight_client.jsonl","flight_server.jsonl","actual_sound_events.jsonl"))Files.deleteIfExists(OUT.resolve(file));mc.options.pauseOnLostFocus=false;mc.options.hideGui=false;mc.options.setCameraType(CameraType.FIRST_PERSON);mc.setCameraEntity(mc.player);org.lwjgl.glfw.GLFW.glfwFocusWindow(mc.getWindow().getWindow());server(p->{p.stopRiding();pilotId=p.getUUID();for(var entity:p.serverLevel().getAllEntities())if(entity instanceof TitanEntity)entity.discard();for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++)p.serverLevel().setBlock(new BlockPos(x,79,z),Blocks.STONE.defaultBlockState(),3);for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)for(int y=80;y<=160;y++)p.serverLevel().setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);p.setGameMode(GameType.SURVIVAL);p.getAbilities().flying=false;p.getAbilities().mayfly=false;p.setNoGravity(false);p.onUpdateAbilities();p.setHealth(p.getMaxHealth());p.getFoodData().setFoodLevel(20);p.removeAllEffects();p.connection.teleport(.5,80,4.5,0,0);var t=BT7274Mod.TITAN.get().create(p.serverLevel());t.setOwner(p.getUUID());t.setNoAi(true);t.setPos(.5,80,.5);p.serverLevel().addFreshEntity(t);titanId=t.getUUID();initialized=true;});}
   if(tick==15)server(p->{var t=(TitanEntity)p.serverLevel().getEntity(titanId);t.interact(p,net.minecraft.world.InteractionHand.MAIN_HAND);check(p.getVehicle()==t,"normal survival interaction starts boarding");});
   if(tick==105)server(p->{var t=(TitanEntity)p.serverLevel().getEntity(titanId);check(p.getVehicle()==t&&!p.getAbilities().flying&&!p.getAbilities().mayfly&&!p.isNoGravity(),"survival pilot seated with flying disabled and gravity enabled");check(t.getAction().equals("idle"),"boarding complete before real G confirmation input");});
   if(tick==113)server(p->{var t=(TitanEntity)p.serverLevel().getEntity(titanId);confirmed=t.getEjectConfirmTicks()>0&&t.getEjectTicks()==0;check(confirmed,"first real G key input requests confirmation through normal client packet");});
   if(tick==119)server(p->{var t=(TitanEntity)p.serverLevel().getEntity(titanId);started=t.getEjectTicks()>0;check(started&&confirmed,"second real G key input starts ejection through normal client packet");});
   if(tick>1)write("flight_client.jsonl",context());
   if(Boolean.getBoolean("bt.qaRecord")&&tick>=95&&tick<=450){var dir=OUT.resolve("frames");Files.createDirectories(dir);String name=String.format(java.util.Locale.ROOT,"frame_%06d.png",tick-95);var row=context();row.put("frame_filename",name);row.put("capture_submitted_unix_ms",System.currentTimeMillis());write("frame_submissions.jsonl",row);Screenshot.grab(dir.toFile(),name,mc.getMainRenderTarget(),message->{});}
   if(serverComplete){Files.writeString(OUT.resolve("complete.txt"),"Survival real G-double-confirm ejection reached ascent, apex, descent and ground. Original native staged audio recorded separately. No production physics changed.");mc.stop();}
   if(tick>600)throw new AssertionError("Survival ejection flight did not finish within600 ticks; inspect both side flight logs");
  }catch(Exception failure){throw new RuntimeException(failure);}
 }
 @SubscribeEvent public static void serverTick(ServerTickEvent.Post event){if(!Boolean.getBoolean("bt.bbEjectionFlightQa")||!initialized||serverComplete)return;var p=event.getServer().getPlayerList().getPlayer(pilotId);if(p==null)return;var e=p.serverLevel().getEntity(titanId);var t=e instanceof TitanEntity titan?titan:null;Map<String,Object> row=new LinkedHashMap<>();row.put("server_tick",event.getServer().getTickCount());row.put("game_tick",p.serverLevel().getGameTime());row.put("wall_time_unix_ms",System.currentTimeMillis());row.put("pilot_y",p.getY());row.put("pilot_vy",p.getDeltaMovement().y);row.put("mounted",p.getVehicle()!=null);row.put("flying",p.getAbilities().flying);row.put("mayfly",p.getAbilities().mayfly);row.put("on_ground",p.onGround());row.put("no_gravity",p.isNoGravity());if(t!=null){row.put("body_action",t.getAction());row.put("body_elapsed_seconds",(p.serverLevel().getGameTime()-t.getActionStartTick())/20.0);row.put("eject_remaining",t.getEjectTicks());}write("flight_server.jsonl",row);
  if(started&&!released&&p.getVehicle()==null){released=true;releaseServerTick=event.getServer().getTickCount();peakY=p.getY();lastY=p.getY();check(p.getY()>86,"ejection release actually places survival pilot above Titan");}
  if(released){peakY=Math.max(peakY,p.getY());if(p.getY()>lastY+.005)ascending=true;if(ascending&&p.getY()<lastY-.002)descending=true;if(descending&&p.onGround()&&event.getServer().getTickCount()-releaseServerTick>10&&!landed){landed=true;landServerTick=event.getServer().getTickCount();check(peakY>88,"actual ejection climbs beyond release teleport");check(p.isAlive(),"survival pilot survives complete native ejection flight and landing");check(ascending&&descending,"actual pilot trajectory includes ascent and descent");check(!p.getAbilities().flying&&!p.getAbilities().mayfly&&!p.isNoGravity(),"flight remains survival physics without creative hover");write("flight_summary.jsonl",Map.of("peak_y",peakY,"land_y",p.getY(),"flight_ticks",event.getServer().getTickCount()-releaseServerTick));}lastY=p.getY();if(landed&&event.getServer().getTickCount()-landServerTick>=20){serverComplete=true;}}
 }
}
